// Student Hub service worker — cautious Phase 1 foundation.
// Caches ONLY the static app shell (HTML/CSS/JS/icons; list generated by scripts/generate-sw.js). It never caches: anything
// admin-related, /api/* responses, authentication responses, private data, session data, or user documents.
// Strategy: network-first with cache fallback, so updates arrive immediately online and the shell still opens offline.
// Offline drafts/sync are NOT implemented here (Phase 6). Requires HTTPS or localhost.
const VERSION = 'v2';
const SHELL_CACHE = `studenthub-shell-${VERSION}`;
const RUNTIME_PREFIX = 'studenthub-runtime';
/* PRECACHE:START (generated by scripts/generate-sw.js) */
const SHELL = [
  '/',
  '/index.html',
  '/login.html',
  '/register.html',
  '/forgot-password.html',
  '/manifest.json',
  '/assets/css/base.css',
  '/assets/css/components.css',
  '/assets/css/layout.css',
  '/assets/css/pages.css',
  '/assets/css/responsive.css',
  '/assets/css/tokens.css',
  '/assets/icons/icon-192.png',
  '/assets/icons/icon-512.png',
  '/assets/icons/icon-maskable-512.png',
  '/assets/icons/icon.svg',
  '/assets/js/api.js',
  '/assets/js/app.js',
  '/assets/js/auth-client.js',
  '/assets/js/components/file-preview.js',
  '/assets/js/components/icons.js',
  '/assets/js/components/modal.js',
  '/assets/js/components/navigation.js',
  '/assets/js/components/pwa.js',
  '/assets/js/components/session.js',
  '/assets/js/components/settings-drawer.js',
  '/assets/js/components/states.js',
  '/assets/js/components/toast.js',
  '/assets/js/components/util.js',
  '/assets/js/mock-data.js',
  '/assets/js/pages/account.js',
  '/assets/js/pages/auth.js',
  '/assets/js/pages/feeds.js',
  '/assets/js/pages/general-assignments.js',
  '/assets/js/pages/home.js',
  '/assets/js/pages/my-assignments.js',
  '/assets/js/router.js',
  '/assets/js/storage.js',
  '/assets/js/theme-init.js'
];
/* PRECACHE:END */

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(SHELL_CACHE).then((c) => c.addAll(SHELL)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('studenthub-') && k !== SHELL_CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

// Called on sign-out so nothing user-specific can linger on a shared device.
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'CLEAR_USER_CACHES') {
    event.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k.startsWith(RUNTIME_PREFIX)).map((k) => caches.delete(k)))));
  }
});

function isCacheable(url) {
  if (url.origin !== self.location.origin) return false;
  const p = url.pathname;
  if (/admin/i.test(p) || p.startsWith('/api/')) return false; // admin UI/code and all API traffic are never cached
  return SHELL.includes(p);
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (!isCacheable(url) && !(req.mode === 'navigate' && url.origin === self.location.origin && !url.pathname.startsWith('/admin'))) return; // let the browser handle everything else
  event.respondWith(
    fetch(req).then((res) => {
      const noStore = (res.headers.get('Cache-Control') || '').includes('no-store');
      if (res.ok && !noStore && isCacheable(url)) {
        const copy = res.clone();
        caches.open(SHELL_CACHE).then((c) => c.put(req, copy));
      }
      return res;
    }).catch(async () => {
      const hit = await caches.match(req, { ignoreSearch: true });
      if (hit) return hit;
      if (req.mode === 'navigate') return (await caches.match('/index.html')) || Response.error();
      return Response.error();
    })
  );
});
